{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'total_weight': 0.0, 'edges': []}
    node_set = set(nodes)
    if len(node_set) != n:
        raise ValueError('Duplicate nodes')
    for node in core_distance:
        if node not in node_set:
            raise ValueError('core_distance contains unknown node')
    # Build all edges with mutual reachability
    edges = []
    for a, b, d in distances:
        if a not in node_set or b not in node_set:
            raise ValueError('distance references unknown node')
        if a == b:
            continue  # ignore self-loops
        # canonicalize: a < b
        if a > b:
            a, b = b, a
        # mutual reachability
        w = max(core_distance[a], core_distance[b], d)
        edges.append((w, a, b))
    # sort deterministically: weight, then a, then b
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # union-find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'total_weight': total_weight, 'edges': mst_edges}"
}
